$spent = 0.0
foreach ($k in $t.Keys) {
  $body = @{ subject=$t[$k]; model="gpt-image-2"; width=1536; height=1024; exact_size=$true; raw=$true } | ConvertTo-Json -Compress
  try { $j = (RUN ("SHOW_IT " + $body)) | ConvertFrom-Json
    if ($j.payload.ok -and $j.payload.id) { $spent += [double]$j.payload.cost_usd; "  " + $k + " -> " + $j.payload.image_url } else { "  " + $k + " -> NOT DRAWN: " + $j.payload.error } } catch { "  " + $k + " -> NOT DRAWN: " + $_.Exception.Message } }
$bn = 'A wide panoramic header banner for the "LGBTQ+ Identity & Pride" category of a tattoo website. On the left, a close-up real photograph, framed close from the waist up so the person fills the full height of the photo and the tattoo is large, sharp and easy to read: a confident person in their twenties with a short bleached buzz cut and a small septum ring, in a white tank top, laughing and flexing their arm toward the camera in warm light. Their upper arm carries a colour tattoo of a waving Progress Pride flag flowing into pink peonies. On the right, on a deep dark background with soft glowing colour, the words "LGBTQ+ Identity & Pride" written large in bold rounded lettering with a rainbow gradient, surrounded by pride tattoo art - a waving rainbow flag, a transgender flag, a bisexual heart, a pink triangle, a lambda symbol, two joined hands and small stars. The art fades softly into the photo through drifting rainbow light. Joyful, proud and vivid, high detail. Only the words "LGBTQ+ Identity & Pride", no other text, no watermark, no logos.'
$body = @{ subject=$bn; model="gpt-image-2"; width=2048; height=768; exact_size=$true; raw=$true } | ConvertTo-Json -Compress
try { $j = (RUN ("SHOW_IT " + $body)) | ConvertFrom-Json
  if ($j.payload.ok -and $j.payload.id) { $spent += [double]$j.payload.cost_usd; "  BANNER LGBTQ+ -> " + $j.payload.image_url } else { "  BANNER LGBTQ+ -> NOT DRAWN: " + $j.payload.error } } catch { "  BANNER LGBTQ+ -> NOT DRAWN: " + $_.Exception.Message }
"== spent this run: $" + [math]::Round($spent, 3)
